def split(val):
    result = {
        "9/12": float('nan'),
        "9/13": float('nan'),
        "9/14": float('nan'),
        "9/15": float('nan')
    }
    pairs = val.split(',')
    for pair in pairs:
        date, value_str = pair.split(':')
        value = float(value_str)
        if date in result:
            result[date] = value
    return result
""")

